    CreateApplicationInput.add_member(:application_source_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: ApplicationSourceUri, location_name: 'ApplicationSourceUri', traits: {"smithy.api#documentation" => "<p>The location of the content that you want to stream. Enter an Amazon S3 URI to a bucket that contains your game or other application. The location can have a multi-level prefix structure, but it must include all the files needed to run the content. Amazon GameLift Streams copies everything under the specified location.</p> <p>This value is immutable. To designate a different content location, create a new application.</p> <note> <p>The Amazon S3 bucket and the Amazon GameLift Streams application must be in the same Amazon Web Services Region.</p> </note>", "smithy.api#required" => {}}))
    CreateApplicationInput.add_member(:application_log_paths, Smithy::Schema::Shapes::ShapeRef.new(shape: FilePaths, location_name: 'ApplicationLogPaths', traits: {"smithy.api#documentation" => "<p>Locations of log files that your content generates during a stream session. Enter path values that are relative to the <code>ApplicationSourceUri</code> location. You can specify up to 10 log paths. Amazon GameLift Streams uploads designated log files to the Amazon S3 bucket that you specify in <code>ApplicationLogOutputUri</code> at the end of a stream session. To retrieve stored log files, call <a href=\"https://docs.aws.amazon.com/gameliftstreams/latest/apireference/API_GetStreamSession.html\">GetStreamSession</a> and get the <code>LogFileLocationUri</code>.</p>"}))
    CreateApplicationInput.add_member(:application_log_output_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: ApplicationLogOutputUri, location_name: 'ApplicationLogOutputUri', traits: {"smithy.api#documentation" => "<p>An Amazon S3 URI to a bucket where you would like Amazon GameLift Streams to save application logs. Required if you specify one or more <code>ApplicationLogPaths</code>.</p> <note> <p>The log bucket must have permissions that give Amazon GameLift Streams access to write the log files. For more information, see <a href=\"https://docs.aws.amazon.com/gameliftstreams/latest/developerguide/applications.html#application-bucket-permission-template\">Application log bucket permission policy</a> in the <i>Amazon GameLift Streams Developer Guide</i>.</p> </note>"}))
